/**
 * meow-vision 配置 tab(设置弹窗「meow-vision」section)。
 *
 * 两块配置,数据全部经 node 半同源 /api/meow-vision/* 获取/保存:
 *   1. 视觉模型:meow_vision 工具用的视觉模型(provider + model);
 *   2. 预览配置:meow_preview 工具用的库包名 / 端口 / .preview 位置。
 *
 * 浏览器半零本地文件读取、零 dsh wire 依赖,只走同源 fetch(与 meow-file-view 的浏览器半一致)。
 */

import { useEffect, useState } from 'react'

/** 一个视觉模型候选(来自 node 半)。 */
interface VisionCandidate {
  provider: string
  providerName?: string
  model: string
  modelName?: string
}

/** 当前视觉配置(provider + model)。 */
interface VisionConfig {
  provider: string
  model: string
}

/** 预览配置。 */
interface PreviewConfig {
  libName: string
  port: number
  previewDir: string
}

/** 组合值分隔符(provider/model id 里不会出现)。 */
const SEP = '::'

/** 设置弹窗 section 的 owner props(本 tab 不消费 close)。 */
export interface VisionModelSectionProps {
  /** settings.section owner share(关闭设置面板);本 tab 不需要。 */
  close?: () => void
}

/** 同源 fetch + 解析 JSON(失败抛错)。 */
async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  const data = (await res.json()) as T
  if (!res.ok) {
    const message = (data as { error?: unknown }).error
    throw new Error(typeof message === 'string' ? message : `请求失败 (${res.status})`)
  }
  return data
}

/**
 * meow-vision 配置 tab:视觉模型 + 预览配置。
 */
export function VisionModelSection(_props: VisionModelSectionProps): JSX.Element {
  // ---- 视觉模型 ----
  const [candidates, setCandidates] = useState<VisionCandidate[]>([])
  const [provider, setProvider] = useState('')
  const [model, setModel] = useState('')
  // ---- 预览配置 ----
  const [pvLib, setPvLib] = useState('')
  const [pvPort, setPvPort] = useState<number>(4173)
  const [pvDir, setPvDir] = useState('')
  // ---- 状态 ----
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState<string | null>(null)
  const [pvSaving, setPvSaving] = useState(false)
  const [pvMessage, setPvMessage] = useState<string | null>(null)

  // 首次挂载:并行拉候选 + 视觉配置 + 预览配置。
  useEffect(() => {
    let cancelled = false
    void Promise.all([
      fetchJson<{ candidates: VisionCandidate[] }>('/api/meow-vision/candidates'),
      fetchJson<{ config: VisionConfig | null }>('/api/meow-vision/config'),
      fetchJson<{ config: PreviewConfig }>('/api/meow-vision/preview-config'),
    ])
      .then(([cand, cfg, pv]) => {
        if (cancelled) return
        setCandidates(cand.candidates ?? [])
        const current = cfg.config
        setProvider(current?.provider ?? '')
        setModel(current?.model ?? '')
        setPvLib(pv.config.libName ?? '')
        setPvPort(pv.config.port ?? 4173)
        setPvDir(pv.config.previewDir ?? '')
        setStatus('ready')
      })
      .catch(() => {
        if (!cancelled) setStatus('error')
      })
    return () => { cancelled = true }
  }, [])

  /** 保存视觉模型选择到 vision.json。 */
  async function saveVision(): Promise<void> {
    if (!provider || !model) {
      setMessage('请先选择一个视觉模型')
      return
    }
    setSaving(true)
    setMessage(null)
    try {
      await fetchJson<{ ok: boolean }>('/api/meow-vision/config', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ provider, model }),
      })
      setMessage('已保存 ✓')
    } catch (error) {
      setMessage(error instanceof Error ? error.message : '保存失败')
    } finally {
      setSaving(false)
    }
  }

  /** 保存预览配置到 preview.json。 */
  async function savePreview(): Promise<void> {
    setPvSaving(true)
    setPvMessage(null)
    try {
      await fetchJson<{ ok: boolean }>('/api/meow-vision/preview-config', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ libName: pvLib, port: pvPort, previewDir: pvDir }),
      })
      setPvMessage('已保存 ✓')
    } catch (error) {
      setPvMessage(error instanceof Error ? error.message : '保存失败')
    } finally {
      setPvSaving(false)
    }
  }

  // 按 provider 分组;当前组合值。
  const groups = new Map<string, VisionCandidate[]>()
  for (const c of candidates) {
    const list = groups.get(c.provider) ?? []
    list.push(c)
    groups.set(c.provider, list)
  }
  const currentValue = provider && model ? `${provider}${SEP}${model}` : ''

  if (status === 'loading') {
    return <p>加载中…</p>
  }
  if (status === 'error') {
    return <p>加载失败：无法访问 /api/meow-vision/*（插件 node 半未加载？）</p>
  }

  const inputStyle = { padding: '6px 8px', minWidth: '280px' }
  const rowStyle = { display: 'flex', alignItems: 'center', gap: '12px' }
  const labelStyle = { display: 'flex', flexDirection: 'column' as const, gap: '4px' }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px', maxWidth: '560px' }}>
      {/* ---------- 视觉模型 ---------- */}
      <section style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <h3 style={{ margin: 0, fontSize: '15px' }}>视觉模型（meow_vision）</h3>
        <p style={{ margin: 0 }}>
          为 <code>meow_vision</code> 工具选择视觉模型。非多模态模型调用 <code>meow_vision</code> 看图时，
          由所选视觉模型识别图片并返回文字描述。
        </p>

        <label style={labelStyle}>
          <span>视觉模型</span>
          <select
            value={currentValue}
            onChange={(e) => {
              const v = e.target.value
              if (!v) { setProvider(''); setModel(''); return }
              const [p, m] = v.split(SEP)
              setProvider(p)
              setModel(m)
            }}
            style={inputStyle}
          >
            <option value="">（未选择）</option>
            {[...groups.entries()].map(([p, list]) => (
              <optgroup key={p} label={list[0]?.providerName ?? p}>
                {list.map((c) => (
                  <option key={`${c.provider}${SEP}${c.model}`} value={`${c.provider}${SEP}${c.model}`}>
                    {c.modelName ?? c.model}
                  </option>
                ))}
              </optgroup>
            ))}
          </select>
          {candidates.length === 0 && (
            <span style={{ color: '#b45309' }}>
              未找到视觉模型。请先在 设置 → 模型 里添加一个支持图片输入的 provider / 模型。
            </span>
          )}
        </label>

        <div style={rowStyle}>
          <button onClick={() => void saveVision()} disabled={saving || candidates.length === 0} style={{ padding: '6px 16px' }}>
            {saving ? '保存中…' : '保存'}
          </button>
          {message !== null && <span>{message}</span>}
        </div>
      </section>

      {/* ---------- 预览配置 ---------- */}
      <section style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <h3 style={{ margin: 0, fontSize: '15px' }}>预览配置（meow_preview）</h3>
        <p style={{ margin: 0 }}>
          为 <code>meow_preview</code> 配置预览工程。模型写一个 Vue demo 后渲染截图，研究组件实际渲染效果。
        </p>

        <label style={labelStyle}>
          <span>团队 UI 库包名（libName）</span>
          <input
            type="text"
            value={pvLib}
            placeholder="如 @sky/sky-ui（留空则组件 demo 无法 import）"
            onChange={(e) => setPvLib(e.target.value)}
            style={inputStyle}
          />
        </label>

        <label style={labelStyle}>
          <span>预览端口</span>
          <input
            type="number"
            value={pvPort}
            min={1}
            max={65535}
            onChange={(e) => setPvPort(Number(e.target.value))}
            style={{ padding: '6px 8px', width: '140px' }}
          />
        </label>

        <label style={labelStyle}>
          <span>.preview 生成位置（留空 = 工作区根）</span>
          <input
            type="text"
            value={pvDir}
            placeholder="留空则生成到会话工作区根目录"
            onChange={(e) => setPvDir(e.target.value)}
            style={inputStyle}
          />
        </label>

        <div style={rowStyle}>
          <button onClick={() => void savePreview()} disabled={pvSaving} style={{ padding: '6px 16px' }}>
            {pvSaving ? '保存中…' : '保存'}
          </button>
          {pvMessage !== null && <span>{pvMessage}</span>}
        </div>
      </section>
    </div>
  )
}
