/**
 * meow-vision 浏览器半（browser half）入口。
 *
 * 双面插件包：node 半负责 Web 路由（/api/meow-vision/*）+ meow_vision 工具 + 系统提示；
 * 本 browser 半用 dsh 的 slot 系统向 dsh web SPA 注入 UI：
 *   `settings.section` —— 设置弹窗（左下角齿轮）新增「视觉」tab，配置视觉模型。
 *
 * 构建：`tsdown.config.ts` 用 dsh 的 clientBundle 结构产出 `lib/client.js`。
 * 浏览器半不读本地文件、不依赖 dsh wire API，全部数据经 node 半同源 /api/meow-vision/* fetch。
 *
 * 注意（类型面）：本文件对 `@deepseek-ai/*` 全部为 type-only import（含 SlotMap 合并），
 * 运行时零跨插件值导入 → 通过 client bundle 纯度门禁。
 */
import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'
// Type-only：加载 ui-settings 的 SlotMap 合并，
// 使 `settings.section` 成为已声明的 slot 键。
import type {} from '@deepseek-ai/dsh-client-ui-settings/client'
import { VisionModelSection } from './VisionModelSection.tsx'

export { VisionModelSection } from './VisionModelSection.tsx'
export type { VisionModelSectionProps } from './VisionModelSection.tsx'

/** 插件名（cordis 诊断标签；loader 条目名仍为包名 meow-vision）。 */
export const name = 'meow-vision-client'

/** 需要的服务：`slots`（SlotRegistry，由 @deepseek-ai/dsh-client-runtime 提供）。 */
export const inject = ['slots']

/**
 * 客户端插件体：注册设置弹窗「视觉」section（slot 注入，随插件卸载自动回收）。
 * @param ctx - 客户端根上下文（含 ctx.slots / ctx.effect 等 cordis 核心面）。
 */
export function apply(ctx: ClientContext): void {
  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: 'meow-vision',   // 导航 key（section id）
    order: 40,           // Models(10) / Plugins(15) 之后
    label: () => 'meow-vision',  // 视觉模型 + 预览配置 两块配置
  }, VisionModelSection))
}
